using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.JNT.Juntas;namespace GraphApi.Services.JNT.Juntas{    public class JuntasService : IJuntasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public JuntasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadJuntas>> GetJuntas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM jnt.Juntas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadJuntas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetJuntasDynamic(            int? juntaID,            string? titulo,            string? descripcion,            DateTime? fechaProgramada,            string? ubicacion,            bool? bActivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "JuntaID, Titulo, Descripcion, FechaProgramada, Ubicacion, bActivo, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM jnt.Juntas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (juntaID.HasValue)            {                vSql.Append(" AND JuntaID = @JuntaID");                vParameters.Add("JuntaID",juntaID);            }            if (!string.IsNullOrWhiteSpace(titulo))            {                vSql.Append(" AND Titulo LIKE @Titulo");                vParameters.Add("Titulo",$"%{titulo}%");            }            if (!string.IsNullOrWhiteSpace(descripcion))            {                vSql.Append(" AND Descripcion LIKE @Descripcion");                vParameters.Add("Descripcion",$"%{descripcion}%");            }            if (!string.IsNullOrWhiteSpace(ubicacion))            {                vSql.Append(" AND Ubicacion LIKE @Ubicacion");                vParameters.Add("Ubicacion",$"%{ubicacion}%");            }            if (bActivo.HasValue)            {                vSql.Append(" AND bActivo = @bActivo");                vParameters.Add("bActivo", bActivo.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadJuntas> CreateJuntas(clCreateJuntas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO jnt.Juntas                (Titulo, Descripcion, FechaProgramada, Ubicacion, bActivo, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Titulo, @Descripcion, @FechaProgramada, @Ubicacion, @bActivo, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Titulo,                objInput.Descripcion,                objInput.FechaProgramada,                objInput.Ubicacion,                objInput.bActivo,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT JuntaID, Titulo, Descripcion, FechaProgramada, Ubicacion, bActivo, bEliminado                FROM jnt.Juntas (NOLOCK)                WHERE JuntaID = @JuntaID;";            var vReadParams = new { JuntaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadJuntas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Junta con ID {vNewId}.");            return vCreated;        }        public async Task<clReadJuntas?> UpdateJuntas(clUpdateJuntas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("JuntaID", objInput.JuntaID);            if (objInput.Titulo is not null)            {                vSets.Add("Titulo = @Titulo");                vParameters.Add("Titulo", objInput.Titulo);            }            if (objInput.Descripcion is not null)            {                vSets.Add("Descripcion = @Descripcion");                vParameters.Add("Descripcion", objInput.Descripcion);            }            if (objInput.FechaProgramada != null)            {                vSets.Add("FechaProgramada = @FechaProgramada");                vParameters.Add("FechaProgramada", objInput.FechaProgramada);            }            if (objInput.Ubicacion is not null)            {                vSets.Add("Ubicacion = @Ubicacion");                vParameters.Add("Ubicacion", objInput.Ubicacion);            }            if (objInput.bActivo != null)            {                vSets.Add("bActivo = @bActivo");                vParameters.Add("bActivo", objInput.bActivo);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE jnt.Juntas                SET {vSetClause}                WHERE JuntaID = @JuntaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT JuntaID, Titulo, Descripcion, FechaProgramada, Ubicacion, bActivo, bEliminado                FROM jnt.Juntas (NOLOCK)                WHERE JuntaID = @JuntaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadJuntas>(sSelect, new {  objInput.JuntaID });        }        public async Task<bool> DeleteJuntas(int nJuntasID)        {            const string sSql = @"                DELETE FROM jnt.Juntas                WHERE JuntaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nJuntasID });            return vAffected > 0;        }    }}